import * as React from "react"

import { cn } from "@/lib/utils"

/** A real sequence, numbered. Only use it when the order matters. */
function Steps({ className, ...props }: React.ComponentProps<"ol">) {
  return <ol data-slot="steps" className={cn("db-steps", className)} {...props} />
}

type StepProps = React.ComponentProps<"li"> & {
  /** The step the person is on: its numeral is the view's one accent. */
  current?: boolean
  done?: boolean
}

function Step({ className, current, done, ...props }: StepProps) {
  return (
    <li
      data-slot="step"
      data-current={current || undefined}
      data-done={done || undefined}
      aria-current={current ? "step" : undefined}
      className={cn("db-step", className)}
      {...props}
    />
  )
}

function StepTitle({ className, ...props }: React.ComponentProps<"h3">) {
  return <h3 data-slot="step-title" className={cn("db-step-title", className)} {...props} />
}

export { Steps, Step, StepTitle, type StepProps }

@layer components {
  /* ── db-steps ── a real sequence: large thin numerals in pencil, a hairline
     between steps (after "Less is more"); the current numeral is the one accent
     and lands with a small rebound when the sequence moves on. */
  .db-steps { list-style: none; margin: 0; padding: 0; counter-reset: db-step; display: grid; gap: var(--db-space-6); }
  .db-step {
    counter-increment: db-step;
    display: grid; grid-template-columns: 3.2ch minmax(0, 1fr); column-gap: var(--db-space-5);
    padding-block-start: var(--db-space-4); border-block-start: var(--db-hairline) solid var(--db-rule);
  }
  .db-step::before {
    content: counter(db-step); grid-row: 1 / span 3; align-self: start;
    font-size: var(--db-f); line-height: 0.9; font-weight: 200; font-stretch: 88%;
    font-variant-numeric: lining-nums tabular-nums; color: var(--db-pencil);
  }
  .db-step > * { grid-column: 2; min-inline-size: 0; }
  .db-step > * + * { margin-block-start: var(--db-space-3); } /* not row-gap: the numeral's spanned rows would each add one */
  .db-step[data-done]::before { color: var(--db-ink); }
  .db-step[data-current]::before { color: var(--db-accent); font-weight: 300; animation: db-land var(--db-moderato) var(--db-spiccato); }
  .db-step-title { margin: 0; font-size: var(--db-mp); line-height: var(--db-mp-lh); letter-spacing: var(--db-mp-tr); font-weight: 400; color: var(--db-ink); }
}
